cat > /tmp/test-custom-metric.mjs << 'EOF'
import { Eval } from '/private/tmp/100-tricks-runs/d03/without/h2-eval-thresholds/r1/packages/frai-core/src/index.js';

// Custom metric
function customMetric(outputs) {
  return {
    id: 'custom_score',
    label: 'Custom Score',
    score: 0.8,
    total: outputs.length
  };
}

// Test with custom metric
const evaluations = Eval.runEvaluations({
  outputs: ['a', 'b', 'c'],
  references: ['a', 'b', 'd'],
  metrics: [customMetric]
});

console.log('Evaluations:', JSON.stringify(evaluations, null, 2));

// Validate and evaluate thresholds
const validation = Eval.validateThresholds({ custom_score: 0.7 }, evaluations);
console.log('Validation:', validation);

const result = Eval.evaluateThresholds({ custom_score: 0.7 }, evaluations);
console.log('Threshold result:', JSON.stringify(result, null, 2));

// Generate report with thresholds
const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { custom_score: 0.7 }
});

console.log('Report passed:', report.passed);
console.log('Report thresholds:', JSON.stringify(report.thresholds, null, 2));
EOF
node /tmp/test-custom-metric.mjs
